//go:build ignore

// Run in a separate module pinned to go-vectorstore v0.4.0; see README.md.
package main

import (
	"context"
	"crypto/sha256"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/gabisonia/go-vectorstore/stores/sqlite"
	"github.com/gabisonia/go-vectorstore/vectordata"
)

func main() {
	out := flag.String("out", "", "New output directory")
	flag.Parse()
	if *out == "" {
		panic("out required")
	}
	if err := os.MkdirAll(*out, 0755); err != nil {
		panic(err)
	}
	path := filepath.Join(*out, "format1.db")
	if _, err := os.Stat(path); !os.IsNotExist(err) {
		panic("database already exists")
	}
	ctx := context.Background()
	store, err := sqlite.Open(ctx, path, sqlite.StoreOptions{})
	if err != nil {
		panic(err)
	}
	definitions := map[string]vectordata.CollectionDefinition{}
	golden := map[string][]vectordata.ModelRecord{}
	d := vectordata.CollectionDefinition{Key: vectordata.KeyProperty{Name: "ID", Type: vectordata.KeyInt64, AutoGenerated: true}}
	for _, p := range []vectordata.DataProperty{
		{Name: "Name", Type: vectordata.TypeString}, {Name: "Int", Type: vectordata.TypeInt64}, {Name: "Float", Type: vectordata.TypeFloat64}, {Name: "Bool", Type: vectordata.TypeBool}, {Name: "Time", Type: vectordata.TypeTime}, {Name: "Strings", Type: vectordata.TypeStringArray}, {Name: "JSON", Type: vectordata.TypeJSON},
		{Name: "UUID", Type: vectordata.TypeUUID}, {Name: "Bytes", Type: vectordata.TypeBytes}, {Name: "Ints", Type: vectordata.TypeInt64Array}, {Name: "Floats", Type: vectordata.TypeFloat64Array}, {Name: "Bools", Type: vectordata.TypeBoolArray}, {Name: "UUIDs", Type: vectordata.TypeUUIDArray}, {Name: "Times", Type: vectordata.TypeTimeArray},
		{Name: "Date", Type: vectordata.TypeDateOnly}, {Name: "Clock", Type: vectordata.TypeTimeOnly}, {Name: "Dates", Type: vectordata.TypeDateOnlyArray}, {Name: "Clocks", Type: vectordata.TypeTimeOnlyArray}, {Name: "Decimal", Type: vectordata.TypeDecimal}, {Name: "Decimals", Type: vectordata.TypeDecimalArray}, {Name: "SQLJSON", Type: vectordata.TypeJSON},
	} {
		p.Optional = true
		d.Data = append(d.Data, p)
	}
	d.Vectors = []vectordata.VectorProperty{
		{Name: "Dense", Dimensions: 2, Metric: vectordata.DistanceL2, Optional: true},
		{Name: "Half", Dimensions: 2, Metric: vectordata.DistanceL2, Precision: vectordata.VectorFloat16, Optional: true},
		{Name: "Bits", Kind: vectordata.VectorBinary, Dimensions: 8, Optional: true},
		{Name: "Sparse", Kind: vectordata.VectorSparse, Dimensions: 4, Metric: vectordata.DistanceL2, Optional: true},
	}
	uuid := "8f516db6-38ca-4e8f-ad79-d71b015f5419"
	instant := time.Date(2026, 1, 2, 3, 4, 5, 123456000, time.UTC)
	bits, err := vectordata.NewBinaryVector([]byte{0xa5}, 8)
	if err != nil {
		panic(err)
	}
	sparse, err := vectordata.NewSparseVector(4, []int{1, 3}, []float32{.25, 1.5})
	if err != nil {
		panic(err)
	}
	records := []vectordata.ModelRecord{
		{Data: map[string]any{"Name": "kept", "Int": int64(9007199254740993), "Float": 1.25, "Bool": true, "Time": instant, "Strings": []string{"a", "b"}, "JSON": map[string]any{"n": json.Number("9007199254740993"), "null": nil}, "UUID": uuid, "Bytes": []byte{0, 128, 255}, "Ints": []int64{-1, 9007199254740993}, "Floats": []float64{1.25, -2.5}, "Bools": []bool{true, false}, "UUIDs": []string{uuid}, "Times": []time.Time{instant}, "Date": "2026-01-02", "Clock": "03:04:05.123456", "Dates": []string{"2026-01-02"}, "Clocks": []string{"03:04:05.123456"}, "Decimal": vectordata.Decimal("9007199254740993.000000001"), "Decimals": []vectordata.Decimal{"0.1", "-1.25"}, "SQLJSON": nil}, Vectors: map[string][]float32{"Dense": {1.25, -2.5}, "Half": {1.1, 2.2}}, BinaryVectors: map[string]vectordata.BinaryVector{"Bits": bits}, SparseVectors: map[string]vectordata.SparseVector{"Sparse": sparse}},
		{Data: map[string]any{"JSON": vectordata.JSONNull{}}},
	}
	fixtures := []struct {
		name       string
		definition vectordata.CollectionDefinition
		rows       []vectordata.ModelRecord
	}{
		{"native", d, records},
		{"uuid", vectordata.CollectionDefinition{Key: vectordata.KeyProperty{Name: "ID", Type: vectordata.KeyUUID}}, []vectordata.ModelRecord{{Key: uuid}}},
		{"required", vectordata.CollectionDefinition{Key: vectordata.KeyProperty{Name: "ID"}, Vectors: []vectordata.VectorProperty{{Name: "V", Dimensions: 2}}}, []vectordata.ModelRecord{{Key: "guide", Vectors: map[string][]float32{"V": {1, 0}}}}},
	}
	for _, fixture := range fixtures {
		c, err := store.EnsureModelCollection(ctx, fixture.name, fixture.definition, vectordata.ModelCollectionOptions{})
		if err != nil {
			panic(err)
		}
		if _, err := c.Insert(ctx, fixture.rows); err != nil {
			panic(err)
		}
		definitions[fixture.name] = c.Definition()
		golden[fixture.name], err = c.Query(ctx, nil, 10, vectordata.QueryOptions{IncludeVectors: true})
		if err != nil {
			panic(err)
		}
	}
	if err := store.Close(); err != nil {
		panic(err)
	}
	write := func(name string, value any) {
		data, err := json.MarshalIndent(value, "", "  ")
		if err != nil {
			panic(err)
		}
		if err := os.WriteFile(filepath.Join(*out, name), append(data, '\n'), 0644); err != nil {
			panic(err)
		}
	}
	write("records.json", struct {
		Definitions map[string]vectordata.CollectionDefinition
		Records     map[string][]vectordata.ModelRecord
	}{definitions, golden})
	data, err := os.ReadFile(path)
	if err != nil {
		panic(err)
	}
	write("manifest.json", struct {
		Release string
		Format  int
		SHA256  string
	}{"v0.4.0", 1, fmt.Sprintf("%x", sha256.Sum256(data))})
}
